-- Task entity storage. Ids are UUIDv7 generated by the application,
-- so no database extension is needed.
CREATE TABLE tasks (
    id          UUID PRIMARY KEY,
    title       TEXT        NOT NULL,
    status      TEXT        NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL,
    updated_at  TIMESTAMPTZ NOT NULL
);

CREATE INDEX tasks_created_at_idx ON tasks (created_at DESC);
